from pathlib import Path
import json,hashlib
H=Path(__file__).resolve().parent
sources=json.loads((H/'source.json').read_text())
sha=lambda x:hashlib.sha256(x.encode()).hexdigest()
# Authored scope and transitional effects, after whole-source/notes/prior-draft reading.
scopes={
'L1242-1':('la limitation du recours au CDD aux seuls emplois non permanents','Les manquements aux conditions de recours concernant les contrats antérieurement conclus restent susceptibles des recours civils prévus par leur régime, sans que cet article autorise un nouveau contrat à terme.'),
'L1242-2':('les six catégories de motifs permettant de conclure un CDD, y compris remplacement, activité temporaire, saison, usage et objet défini','Les qualifications et droits attachés aux contrats antérieurs restent appréciés selon leur régime. Le bulletin unique des contrats de moins d’un mois, les garanties de formation, de reclassement et de priorité de réemploi ne sont pas retirés aux bénéficiaires de ces contrats. Les besoins temporaires peuvent être satisfaits par le contrat unique sans terme ; la fin d’une saison ou d’un projet n’en constitue pas un terme automatique.'),
'L1242-3':('les autorisations de CDD d’insertion, de complément de formation, de recherche et de reconversion','L’abrogation du support CDD n’abroge ni les aides, exonérations et droits de formation régis par leurs textes propres ni leurs conditions de bénéficiaire, de parcours ou de période éligible. Elle n’autorise pas à fixer un terme à un nouvel emploi sous couvert de la durée d’une aide ou d’une formation. Les contrats antérieurs conservent leurs droits et engagements de formation.'),
'L1242-4':('la faculté de conclure un CDD après apprentissage, y compris avant l’accomplissement d’obligations du service national','Les contrats déjà conclus dans ces conditions gardent leur régime et leur terme antérieur. L’achèvement de l’apprentissage ne permet pas de conclure un nouveau CDD ; les droits et dispenses propres au service national demeurent régis par leurs textes.'),
'L1242-5':('l’interdiction particulière de certains CDD durant six mois après licenciement économique et ses deux dérogations','Pour les contrats antérieurs, les conditions et dérogations de trois mois non renouvelables ou de commande exceptionnelle à l’exportation restent prises en compte selon l’ancienne loi. La suppression du recours au CDD ne supprime pas la priorité de réembauche ni les protections du licenciement économique applicables au contrat unique.'),
'L1242-6':('les interdictions spécifiques au CDD de remplacement d’un gréviste et de travaux dangereux, et la procédure de dérogation associée','Les protections contre les atteintes au droit de grève et les règles de santé et de sécurité autonomes demeurent applicables ; l’abrogation ne vaut pas autorisation de les contourner. Pour les contrats antérieurs, les interdictions et les dérogations légalement accordées aux travaux dangereux restent régies par l’ancienne loi ; aucune autorisation nouvelle de CDD ne peut en résulter.'),
'L1242-7':('le terme précis du CDD et les six exceptions permettant un terme défini par un événement','Le terme, la durée minimale et les événements de fin des contrats antérieurement conclus demeurent ceux de leur régime. La survenance d’un événement de remplacement, de saison ou de projet ne fixe pas le terme d’un contrat unique nouvellement conclu.'),
'L1242-8':('le pouvoir de branche de déterminer la durée totale des CDD','Les stipulations antérieures demeurent utilisables pour apprécier les contrats déjà conclus, dans leur champ et avec leurs exclusions, sans autoriser aucun nouveau CDD ni renouvellement après la réforme.'),
'L1242-8-1':('les plafonds supplétifs de dix-huit, neuf et vingt-quatre mois et leurs conditions propres','Les contrats antérieurs restent appréciés selon leurs plafonds, exclusions et garanties applicables, notamment la consultation préalable et le minimum de six mois de la commande exceptionnelle lorsqu’ils étaient requis. Ces règles ne permettent pas de conclure ou renouveler un CDD après l’entrée en vigueur de la réforme.'),
'L1242-8-2':('la durée minimale de dix-huit mois, maximale de trente-six mois et l’absence de renouvellement du CDD à objet défini','Ces bornes et la prohibition de renouvellement continuent de protéger les contrats à objet défini antérieurement conclus, sans créer de nouvelle faculté d’emploi à terme.'),
'L1242-9':('la prise d’effet du CDD de remplacement avant l’absence de la personne remplacée','Les dates d’effet valablement convenues pour les contrats antérieurs restent acquises. Le début anticipé d’un remplacement peut être organisé dans un contrat unique sans lui donner un terme.'),
'L1242-10':('le régime d’essai propre au CDD et ses plafonds selon la durée du contrat','Les essais déjà stipulés sous ce régime restent soumis à leurs limites, notamment les usages et stipulations plus courts. La conversion ne permet pas de recommencer un essai ni de prolonger un essai en cours ; aucune durée nouvelle de l’essai du contrat unique n’est fixée par cet article.'),
'L1242-11':('les quatre exclusions de règles CDD pendant leur période d’essai','Les exclusions et leurs limites continuent de s’appliquer aux essais des contrats antérieurs selon leur régime, sans rétablir un recours futur au CDD ni retirer une dispense favorable déjà applicable.'),
'L1242-12':('l’écrit, le motif de recours et les huit mentions propres au CDD','La régularité des contrats antérieurs et les droits qui en résultent restent appréciés selon la loi qui leur est applicable. L’abrogation des mentions propres au terme ne supprime ni les informations d’emploi, de rémunération et de sécurité légalement dues dans le contrat unique ni les recours afférents aux contrats antérieurs.'),
'L1242-12-1':('les sept mentions supplémentaires du CDD à objet défini','Les clauses et garanties des contrats à objet défini déjà conclus restent régies par l’ancienne loi, notamment le droit à indemnité de dix pour cent dans les cas où il est dû. La durée d’un projet ne peut servir de terme automatique au contrat unique.'),
'L1242-13':('la transmission dans les deux jours ouvrables propre au CDD','Les remises déjà dues au titre des contrats antérieurs et les droits civils liés à un défaut de transmission ne sont pas effacés. Aucune formalité de transmission d’un nouveau CDD n’est maintenue ; les informations d’emploi légalement dues sous le contrat unique conservent leur fondement propre.'),
'L1242-14':('la règle d’assimilation du CDD au CDI à l’exception de la rupture','Les salariés des contrats antérieurs gardent le bénéfice de leurs dispositions légales, conventionnelles et usages applicables, avec les anciennes règles spéciales de rupture. La réforme ne retire aucun droit d’exécution du contrat du seul fait du changement de support.'),
'L1242-15':('la règle de rémunération comparative propre au salarié en CDD','La rémunération minimale de comparaison des contrats antérieurs et les créances qui en résultent restent garanties. La conversion ne permet pas de réduire la rémunération acquise ; les règles générales d’égalité et de non-discrimination restent applicables au contrat unique.'),
'L1242-16':('le régime propre d’indemnité compensatrice de congés payés du CDD','Les droits antérieurs conservent leur calcul, leur minimum du dixième et leur échéance selon l’ancienne loi, y compris la réserve de poursuite en contrat sans terme. Les congés acquis restent conservés en cas de conversion ; aucune indemnité de congés due n’entre dans la franchise ou le plafond de l’indemnité ordinaire de rupture.'),
'L1242-17':('l’information particulière du salarié en CDD sur les postes en CDI après six mois','Ce droit d’information reste ouvert aux titulaires d’un contrat antérieur dans ses conditions, jusqu’à sa fin ou sa conversion. L’abrogation ne fait pas disparaître une demande déjà présentée ni la réponse qui lui est due.'),
'L1243-1':('les causes et échéances spéciales de rupture anticipée du CDD','Les contrats antérieurs gardent leur terme et ne peuvent être rompus sur le seul fondement du préavis du contrat unique ; leurs accords de rupture et leurs causes légales propres demeurent applicables. Les droits des contrats à objet défini restent appréciés selon leurs échéances et motifs antérieurs.'),
'L1243-2':('la faculté de rupture anticipée du CDD par le salarié justifiant d’un CDI','Les salariés des contrats antérieurs conservent cette faculté et ses conditions de préavis, dont le plafond favorable de deux semaines et les accords de dispense. Une conversion consentie en contrat unique ne remet pas à zéro les droits acquis.'),
'L1243-3':('la responsabilité du salarié pour la rupture anticipée irrégulière d’un CDD','Les litiges des contrats antérieurs restent appréciés selon le préjudice réellement subi et les causes de rupture autorisées par leur régime. Cette responsabilité propre au CDD n’est pas étendue au départ régulier d’un salarié sous contrat unique ; aucun forfait nouveau n’est créé.'),
'L1243-4':('la réparation de rupture anticipée du CDD et l’indemnité de sinistre de force majeure','Les salariés des contrats antérieurs conservent, dans les conditions de l’ancienne loi, la réparation minimale des rémunérations restant jusqu’au terme et l’indemnité propre au sinistre de force majeure, ainsi que la prime de fin de contrat lorsqu’elle est due. Ces créances ne sont ni annulées ni plafonnées par le barème ordinaire du contrat unique.'),
'L1243-5':('la cessation de plein droit du CDD au terme et le préavis spécial de l’objet défini','Les contrats antérieurs peuvent atteindre leur terme dans les conditions antérieures, y compris le délai de prévenance de deux mois de l’objet défini. Les protections des victimes d’accident du travail ou de maladie professionnelle et des titulaires d’un mandat demeurent réservées. La fin d’une tâche ne met pas automatiquement fin au contrat unique.'),
'L1243-6':('l’effet de la suspension sur l’échéance du terme du CDD','Les contrats antérieurs restent régis, quant à leur échéance malgré suspension, par leur régime et ses protections spéciales. La suspension d’un contrat unique n’en crée pas le terme ni une cause automatique de rupture.'),
'L1243-7':('le report du terme de remplacement jusqu’au surlendemain de la reprise','Pour les contrats antérieurs de remplacement, le report déjà permis jusqu’au surlendemain de la reprise reste applicable dans son champ exact. Ce seul ajustement légal de l’échéance n’est pas un renouvellement autorisant un nouveau CDD après la réforme.'),
'L1243-8':('la prime de fin de CDD égale à dix pour cent de la rémunération brute','Les contrats antérieurs conservent le droit à cette prime, son assiette, ses conditions, son versement avec le dernier salaire et sa mention sur le bulletin. Les réductions et exclusions légales ou conventionnelles applicables demeurent réservées. Cette prime ancienne n’est ni remplacée ni plafonnée par l’indemnité ordinaire du contrat unique.'),
'L1243-9':('la réduction conventionnelle de la prime à six pour cent en contrepartie de formation','Les contrats antérieurs gardent le bénéfice de cette réduction dans les seules conditions où elle est licite, avec les contreparties de formation, accès au bilan de compétences et garanties prévues. La réforme ne transforme pas le taux réduit en suppression rétroactive d’une prime due.'),
'L1243-10':('les quatre exclusions de prime de fin de CDD','Les exclusions et réserves conventionnelles continuent de s’appliquer aux contrats antérieurs dans leur champ exact : la réforme ne crée pas de prime lorsqu’elle n’était pas due et n’efface pas celle qui reste due. Aucun refus de conversion ne peut modifier rétroactivement les critères légaux de l’ancienne exclusion.'),
'L1243-11':('la transformation du CDD poursuivi au-delà du terme en CDI','La poursuite d’un contrat antérieur après son terme fait naître un contrat unique sans terme. Le salarié conserve l’ancienneté acquise ; la conversion ou la poursuite ne permet pas de recommencer un essai. Les durées déjà accomplies sont prises en compte dans les conditions protectrices de l’ancienne loi.'),
'L1243-11-1':('la notification et le signalement à France Travail du refus d’une proposition de CDI à l’issue d’un CDD','Aucun nouveau signalement n’est exigé sur ce fondement pour un refus intervenant à compter de l’entrée en vigueur de la réforme, y compris à l’issue d’un contrat antérieur. Les informations régulièrement transmises pour des faits antérieurs restent soumises à leurs règles de preuve, de rectification et de recours, sans nouveau relevé récapitulatif.'),
'L1243-12':('la prorogation spéciale du terme liée à l’exposition aux rayonnements ionisants','La prorogation protectrice reste due, dans les conditions de l’ancienne loi, aux salariés titulaires d’un contrat antérieur lorsque leur exposition la justifie. Elle conserve sa méthode proportionnelle, sans nouveau seuil d’exposition, et n’est pas assimilée à un renouvellement ordinaire interdit. Les règles autonomes de radioprotection et de suivi médical restent applicables au contrat unique.'),
'L1243-13':('la compétence de la branche sur le nombre de renouvellements des CDD','Les conditions antérieures servent à apprécier la validité des renouvellements déjà conclus avant la réforme. Aucune clause de contrat ni stipulation collective antérieure ne permet de convenir d’un nouveau renouvellement CDD après son entrée en vigueur.'),
'L1243-13-1':('les deux renouvellements supplétifs de CDD, leur plafond total et leur avenant','La validité des renouvellements déjà conclus est appréciée selon le régime alors applicable, ses plafonds et ses exceptions. Aucun nouvel avenant de renouvellement à terme ne peut être conclu après la réforme ; la poursuite de l’emploi se fait par contrat unique sans terme.'),
'L1244-1':('les quatre catégories permettant des CDD successifs avec un même salarié','Les droits et qualifications des contrats successifs conclus antérieurement restent appréciés selon l’ancienne loi. Les mêmes motifs ne permettent pas la conclusion d’un nouveau CDD après la réforme ; un remplacement ou une saison s’organise dans un emploi sans terme.'),
'L1244-2':('les reconductions saisonnières, garanties conventionnelles de réemploi et cumul d’ancienneté','Les clauses et droits de réemploi déjà attachés aux contrats antérieurs, les indemnités de non-proposition et le cumul d’ancienneté demeurent conservés. Lorsqu’un droit de réemploi se réalise après la réforme, son exécution prend la forme d’un contrat unique sans terme et ne recrée pas un CDD ; les autres conditions et garanties acquises de ce droit restent applicables.'),
'L1244-2-1':('la qualification de successions saisonnières malgré les intersaisons','Le cumul d’ancienneté des contrats saisonniers antérieurs continue de bénéficier aux salariés dans les branches et conditions antérieurement applicables, y compris les interruptions sans activité. Il est conservé lors de la conversion en contrat unique, sans nouvelle succession de CDD.'),
'L1244-2-2':('l’information et le droit supplétif à reconduction après deux mêmes saisons','Les droits de réemploi et d’information acquis au titre des saisons antérieures demeurent applicables dans leur champ, avec la compatibilité de qualification et la réserve du motif dûment fondé. Une proposition due après la réforme porte sur un contrat unique sans terme ; ni la qualification ni l’ancienneté acquises ne sont perdues.'),
'L1244-3':('le délai de carence après CDD pour réoccuper le même poste et sa négociation de branche','Aucun délai de carence propre au présent article ne fait obstacle à une embauche en contrat unique après la réforme. Les litiges des successions de contrats antérieurement conclus restent appréciés dans leur ancien régime. L’abrogation ne modifie pas les règles autonomes du travail temporaire, qui sont coordonnées séparément.'),
'L1244-3-1':('le calcul supplétif de carence au tiers ou à la moitié du CDD','Les faits antérieurs restent appréciés selon les fractions, seuil de quatorze jours et jours d’ouverture antérieurement applicables. Aucun délai de carence sur ce fondement ne peut être exigé pour conclure le contrat unique ; aucune règle d’arrondi ou d’attente de remplacement n’est créée.'),
'L1244-4':('les dispenses conventionnelles du délai de carence propre au CDD','Les dispenses demeurent prises en compte dans les litiges des contrats antérieurs. La suppression de la carence pour le contrat unique est générale dans le champ de cet article et ne retire aucune dispense favorable ; elle ne permet pas de nouveaux CDD.'),
'L1244-4-1':('les sept dispenses supplétives de carence après CDD','Les sept exceptions restent prises en compte pour apprécier les contrats antérieurement conclus, sans aggraver rétroactivement leur régime. Aucun nouveau délai ni preuve répétée de dispense n’est exigé pour l’embauche en contrat unique.'),
'D1242-1':('la liste des dix-sept secteurs autorisant des CDD d’usage','La liste antérieure reste utilisée pour apprécier les droits et la régularité des contrats déjà conclus ; aucune des catégories n’est retranchée rétroactivement. Ces secteurs peuvent employer sous contrat unique sans autorisation de CDD d’usage ; les aides ou avantages sectoriels régis par d’autres dispositions ne sont pas abrogés par cet article.'),
'D1242-3':('les quatre catégories autorisant un CDD de complément de formation','Les droits de formation et d’aide attachés aux contrats antérieurs restent conservés. Pour l’avenir, la période éligible de formation relève de ses dispositions propres dans le contrat unique ; l’abrogation ne transforme pas sa durée en terme automatique d’emploi et n’abroge pas les aides individuelles à la recherche.'),
'D1242-4':('le renvoi à la liste des travaux dangereux interdits aux seuls salariés en CDD','La protection et les dérogations légalement applicables aux contrats antérieurs restent gouvernées par leur régime. Les règles de santé et de sécurité et la liste autonome de D4154-1 ne sont ni abrogées ni modifiées par cet article.'),
'D1242-5':('le renvoi à l’autorisation administrative de dérogation pour travaux dangereux en CDD','Les dérogations accordées et les demandes concernant des contrats antérieurs restent régies par leurs conditions et leurs limites ; l’abrogation ne les convertit pas en autorisations nouvelles de CDD. Les pouvoirs et règles autonomes de santé et de sécurité demeurent applicables.'),
'D1242-6':('les durées des CDD de complément de formation liées au stage, au séjour autorisé et à l’aide recherche','Les contrats antérieurs conservent leurs durées et dérogations dans les conditions de l’ancienne loi. La durée d’une formation, d’une aide ou d’une autorisation de travail reste régie par son texte propre et ne fixe pas par elle-même le terme d’un nouveau contrat unique ; les règles autonomes de séjour et de travail ne sont pas modifiées.'),
'D1242-8':('la procédure de demande et réponse sur les postes CDI accessibles aux salariés en CDD','Pour les titulaires de contrats antérieurs, les demandes et réponses demeurent soumises à l’ancienne procédure et à ses dispenses favorables : limite annuelle et réponse orale autorisée dans son champ. Aucune nouvelle demande n’est créée pour un salarié déjà en contrat unique.'),
'D1243-1':('la règle de calcul de prime invoquée lors d’un départ anticipé de CDD pour CDI','Les créances des contrats antérieurs restent appréciées dans les conditions de l’ancienne loi et sous ses exclusions de prime ; la présente transition ne crée aucun droit à prime absent de ce régime. La discordance entre ce renvoi et les exclusions de L1243-10 n’est pas transformée en nouvel avantage ou prélèvement.'),
'R1243-2':('la procédure de notification et transmission à France Travail du refus de CDI après CDD','Aucune nouvelle transmission ni demande de compléments n’est exigée sur ce fondement pour les refus intervenant après la réforme. Les informations de faits antérieurs et leurs contestations demeurent accessibles dans leurs conditions légales ; aucune nouvelle déclaration de remplacement n’est instituée.'),
}
# Penal sanctions: no new fine; no unlawful blanket perpetuation of the old penalty.
penal_scopes={
'L1248-1':'la conclusion d’un CDD pour pourvoir durablement un emploi normal et permanent',
'L1248-2':'la conclusion d’un CDD hors tâche temporaire ou hors cas légaux',
'L1248-3':'la conclusion d’un CDD en méconnaissance des interdictions de L1242-5 et L1242-6',
'L1248-4':'le défaut de terme précis ou de durée minimale dans un CDD',
'L1248-5':'le dépassement des durées légales ou conventionnelles des CDD',
'L1248-6':'l’absence d’écrit et de définition précise du motif dans un CDD',
'L1248-7':'le défaut de transmission d’un CDD dans le délai sanctionné',
'L1248-8':'la méconnaissance de l’égalité de rémunération propre au CDD',
'L1248-9':'la méconnaissance de la prorogation radioprotectrice propre au CDD',
'L1248-10':'le renouvellement d’un CDD en méconnaissance de ses règles',
'L1248-11':'la succession de contrats sur un même poste en méconnaissance de la carence CDD',
}
special={
'L1241-1':'''<p>I. – À compter de l’entrée en vigueur de la loi instituant le contrat unique de travail, aucun nouveau contrat de travail à durée déterminée ni aucun nouveau renouvellement d’un tel contrat ne peut être conclu sur le fondement du présent titre. Les dispositions qui en permettaient la conclusion ou le renouvellement cessent de produire cet effet. Une stipulation antérieure ne permet pas de convenir d’un nouveau renouvellement après cette date. La poursuite de l’emploi prend la forme du contrat unique sans terme ; une durée de formation, de mission, de saison, de projet ou d’aide ne peut, à elle seule, en fixer la fin automatique.</p>
<p>II. – Les contrats à durée déterminée conclus avant cette entrée en vigueur conservent leur terme, les primes et les droits qui leur sont applicables selon les dispositions légales et conventionnelles antérieures. Celles du présent titre demeurent applicables à ces contrats, dans leur rédaction antérieure, dans la mesure nécessaire à leur exécution, à la détermination et au paiement des sommes dues et à l’exercice des recours, sous les réserves expresses du présent article et des articles qui suppriment une formalité ou une sanction. Les notes transitoires antérieures conservent leur champ propre ; la réforme n’en recommence pas les délais.</p>
<p>Le report légal du terme de remplacement prévu par l’ancien article L. 1243-7 et la prorogation protectrice de radioprotection prévue par l’ancien article L. 1243-12 restent applicables aux contrats antérieurs dans leurs conditions. Ils ne constituent pas des renouvellements ordinaires autorisant un nouveau CDD.</p>
<p>III. – Les parties peuvent convenir de convertir un contrat antérieur en contrat unique sans terme. Cette conversion conserve l’ancienneté et les droits déjà acquis ; elle ne permet pas de recommencer une période d’essai. Elle n’efface aucune rémunération, indemnité de congés, prime déjà due, créance de réparation ni voie de recours. Les indemnités dont l’ouverture dépend de l’arrivée du terme ou de la poursuite en contrat sans terme demeurent appréciées selon leurs conditions antérieures, sans création d’une prime nouvelle du seul fait de la conversion.</p>
<p>La réalisation après la réforme d’un droit acquis de reconduction ou de réemploi saisonnier se fait sous contrat unique sans terme, avec conservation de l’ancienneté et des garanties attachées à ce droit ; elle n’autorise pas un nouveau CDD.</p>
<p>IV. – Les exclusions du présent titre qui concernaient les contrats d’apprentissage et les contrats de mission conclus avec une entreprise de travail temporaire demeurent applicables aux contrats antérieurs de ces régimes. Leur réforme future relève des dispositions qui leur sont propres ; le présent article ne rétablit aucune autorisation nouvelle de contrat à terme. Les droits de formation, les aides, exonérations et avantages régis par des dispositions autonomes ne sont pas abrogés par la suppression du support CDD.</p>
<p>V. – La suppression du régime futur du CDD ne supprime ni les protections contre la discrimination, ni celles liées à la maternité, à la santé, aux mandats, aux libertés fondamentales et à l’exercice d’un recours. Elle ne transforme pas l’indemnité ordinaire de rupture du contrat unique en plafond des salaires, congés, créances antérieures ou réparations d’une illégalité. La loi répressive plus douce reste applicable dans les conditions qui lui sont propres.</p>''',
'L1245-1':'''<p>Tout contrat de travail conclu à compter de l’entrée en vigueur de la loi instituant le contrat unique en méconnaissance de l’interdiction de nouveau CDD ou de renouvellement prévue à l’article L. 1241-1 est réputé conclu sous la forme d’un contrat unique sans terme. La clause de terme est sans effet ; ni l’arrivée de sa date ni l’achèvement de l’objet annoncé ne met fin, à lui seul, à la relation d’emploi.</p>
<p>Cette qualification prend effet au commencement de la relation irrégulièrement assortie d’un terme. Lorsqu’un contrat antérieur est irrégulièrement renouvelé après la réforme, la qualification ne remet pas à zéro l’ancienneté déjà acquise ; les droits attachés à la période antérieure sont conservés.</p>
<p>Les règles du contrat unique relatives à sa rupture et aux réparations d’une rupture illégale demeurent applicables. Le présent article ne crée ni amende ni indemnité forfaitaire de requalification nouvelle.</p>
<p>Les demandes concernant la validité de contrats conclus avant la réforme restent appréciées selon l’ancienne rédaction du présent article et ses conditions de requalification et d’indemnisation, conformément à l’article L. 1241-1. Le seul retard de transmission d’un ancien contrat conserve notamment son régime propre et ne devient pas un motif nouveau de requalification.</p>''',
'L1245-2':'''<p>La demande du salarié tendant à faire reconnaître le contrat unique sans terme en application de l’article L. 1245-1 est portée directement devant le bureau de jugement du conseil de prud’hommes. Celui-ci statue au fond dans le mois suivant sa saisine.</p>
<p>La même procédure demeure ouverte aux demandes de requalification de contrats conclus avant la réforme. Lorsqu’il fait droit à une telle demande régie par l’ancienne loi, le conseil accorde au salarié l’indemnité de requalification prévue par cette loi, d’au moins un mois de salaire, sans préjudice des règles de rupture alors applicables.</p>
<p>Pour les contrats conclus ou renouvelés irrégulièrement après la réforme, la reconnaissance du contrat unique n’est pas subordonnée à une ancienneté minimale ni au paiement de l’indemnité ordinaire de rupture. Les salaires, droits d’exécution et réparations d’une rupture illégale restent dus dans leurs conditions propres. Le forfait d’un mois de l’ancienne requalification du CDD n’est pas étendu à une simple irrégularité d’une formalité qui a été supprimée.</p>''',
'R1245-1':'''<p>La décision du conseil de prud’hommes qui statue sur une demande relevant de l’article L. 1245-2 est exécutoire de droit à titre provisoire.</p>
<p>Cette règle couvre la reconnaissance du contrat unique sans terme prévue par la nouvelle rédaction de cet article et les demandes de requalification de contrats antérieurs demeurées régies par l’ancienne loi. Le changement de dénomination du contrat ne retire pas au salarié cette garantie d’exécution.</p>''',
'L1246-1':'''<p>Dans les secteurs des spectacles, de l’action culturelle, de l’audiovisuel, de la production cinématographique et de l’édition phonographique, les agents de contrôle mentionnés à l’article L. 8112-1, ainsi que les agents du Centre national du cinéma et de l’image animée, des directions régionales des affaires culturelles, de l’institution mentionnée à l’article L. 5312-1 et de l’organisme gestionnaire du régime d’assurance chômage, se communiquent réciproquement, sur demande écrite, les renseignements et documents nécessaires, le cas échéant, à la recherche et à la constatation des manquements aux dispositions mentionnées au 11° et des infractions aux dispositions mentionnées au 12° de l’article L. 421-1 du code du cinéma et de l’image animée.</p>
<p>La communication propre aux infractions de recours au CDD prévues au 3° de l’ancien article L. 1242-2 est supprimée pour l’avenir. Les communications nécessaires aux seules procédures antérieures qui demeurent légalement ouvertes sont régies par l’ancienne loi, sous réserve de l’application de la loi répressive plus douce. Aucun relevé, collecte périodique ou déclaration de remplacement n’est créé.</p>''',
'L1247-1':'''<p>Les organisations syndicales représentatives dans l’entreprise peuvent exercer, en faveur d’un salarié et sans avoir à justifier d’un mandat, les actions en justice résultant du présent titre. Cette faculté couvre les droits conservés des contrats antérieurs et la reconnaissance du contrat unique sans terme en cas de terme nouveau interdit.</p>
<p>Le salarié est averti de la nature et de l’objet de l’action ainsi que de ses droits dans les conditions fixées par voie réglementaire. Le syndicat peut agir si le salarié ne s’y est pas opposé dans les quinze jours suivant la réception de la notification de son intention d’agir.</p>
<p>Le salarié peut toujours intervenir à l’instance et y mettre un terme à tout moment. L’absence d’opposition à l’action ne vaut ni renonciation à un droit matériel ni consentement à une modification du contrat de travail.</p>''',
'D1247-1':'''<p>L’organisation syndicale qui envisage une action en faveur d’un salarié sur le fondement de l’article L. 1247-1 l’en avertit par lettre recommandée avec avis de réception ou par un autre moyen permettant de donner date certaine à sa réception et d’établir le contenu notifié.</p>
<p>La notification indique la nature et l’objet de l’action envisagée et précise :</p>
<p>1° Que l’organisation syndicale conduit l’action et peut elle-même exercer les voies de recours contre le jugement ;</p>
<p>2° Que le salarié peut, à tout moment, intervenir à l’instance ou y mettre un terme ;</p>
<p>3° Qu’il peut s’opposer à l’action en faisant connaître son opposition au syndicat dans les quinze jours suivant la réception de cette notification.</p>
<p>Une notification unique contenant ces informations suffit. La suppression de l’exclusivité de la lettre recommandée ne dispense ni de l’information complète ni de la preuve de sa réception.</p>''',
'D1247-2':'''<p>À l’expiration des quinze jours suivant la réception de la notification conforme à l’article D. 1247-1, l’absence d’opposition du salarié permet au syndicat d’engager l’action prévue à l’article L. 1247-1.</p>
<p>Elle ne prive pas le salarié de son droit d’intervenir à l’instance ou d’y mettre fin à tout moment. Elle ne vaut ni acceptation d’une modification de son contrat ni renonciation à une créance ou à un recours personnel.</p>''',
}
rows=[]
for s in sources:
 n=s['number'];r={k:s[k]for k in ['code_id','source_id','source_sha256','number']};r['status']='rewrite_draft';r['current_beforeimage_sha256']=s['current_beforeimage_sha256'];r['source_body_sha256']=sha(s['source_xml']);r['source_notes_sha256']=sha(s['source_notes_xml'])
 if n in special:
  r['proposed_xml']=special[n];r['reason']='Réforme de fond du contrat unique : '+{'L1241-1':'interdit les nouveaux supports CDD et leurs renouvellements, organise le maintien des anciens termes et droits, la conversion et les réserves de formation/intérim.','L1245-1':'remplace les anciennes causes formelles de requalification par la neutralisation du terme nouveau interdit et la reconnaissance du contrat unique, sans amende ni remise à zéro d’ancienneté.','L1245-2':'maintient la saisine accélérée et les droits anciens de requalification ; sépare leurs indemnités des créances du nouveau contrat.','R1245-1':'maintient l’exécution provisoire de la décision de reconnaissance du contrat sans terme et des requalifications anciennes.','L1246-1':'retire les échanges propres au recours futur au CDD, en conservant le volet CNC distinct qui ne relève pas de sa suppression.','L1247-1':'conserve l’action syndicale sans mandat et le contrôle du salarié, en couvrant les droits anciens et le terme nouveau interdit.','D1247-1':'supprime l’exclusivité du recommandé pour une notification prouvée et complète, sans double démarche ni perte de recours.','D1247-2':'coordonne le délai d’opposition à compter de la réception et maintient le contrôle du salarié sur l’action.'}[n]
  if n in ['L1241-1','L1245-1','L1245-2','L1246-1','D1247-1']:
   r.update(change_type='normative_reduction',reform_policy_id='editorial_direction_2026_10_19',removed_provisions=[{'L1241-1':'Supprime la faculté future de conclure ou de renouveler les anciens supports de CDD, avec transition des droits.','L1245-1':'Retire pour l’avenir les causes formelles de requalification liées aux obligations CDD supprimées.','L1245-2':'Ne reproduit pas un forfait d’ancienne irrégularité CDD à charge de la nouvelle relation d’emploi sans son fait générateur.','L1246-1':'Supprime le volet d’échange de données propre aux infractions de recours au CDD pour les faits futurs.','D1247-1':'Supprime l’exclusivité de la lettre recommandée pour informer complètement le salarié avec preuve de réception.'}[n]])
  r['benefit_review']={'L1241-1':'Les anciens termes, primes, congés, réparations, garanties saisonnières et ancienneté restent protégés. Les prorogations légales de remplacement/radioprotection sont distinguées des nouveaux renouvellements interdits. Les aides et exonérations autonomes ne sont pas abrogées.','L1245-1':'La reconnaissance du contrat unique protège le salarié dès le début de la relation irrégulièrement mise à terme, sans perdre l’ancienneté antérieure. Les anciennes requalifications et leur exception favorable du seul retard de remise restent distinctes.','L1245-2':'L’accès direct au juge et le délai d’un mois demeurent pour les anciens et nouveaux litiges. Les anciens minima d’indemnisation sont conservés ; aucune franchise de rupture ordinaire n’efface salaires, congés ou réparations d’illégalité.','R1245-1':'La protection d’exécution provisoire reste disponible pour la reconnaissance du contrat unique et pour les requalifications des anciens contrats ; l’abandon de l’ancien support CDD ne retire pas un recours favorable.','L1246-1':'La suppression des échanges liés aux anciens motifs de CDD n’efface pas les créances des salariés ni leurs recours. Le volet distinct CNC est conservé dans son champ existant ; aucune nouvelle collecte administrative ne remplace le contrôle retiré.','L1247-1':'La dispense de mandat reste ouverte au salarié pour ses droits anciens et futurs, avec délai d’opposition, intervention et arrêt de l’action à tout moment. Le silence ne devient pas consentement à modifier l’emploi ou renoncer aux droits.','D1247-1':'La notification alternative réduit le coût de procédure sans supprimer les trois informations obligatoires ni la preuve de réception. Le salarié garde quinze jours pour s’opposer et peut ensuite intervenir ou arrêter l’action.','D1247-2':'Le point de départ à réception préserve les quinze jours réels de défense. Le salarié conserve intervention et arrêt de l’instance ; aucun silence procédural ne supprime ses créances ou ne transforme son contrat.'}[n]
 else:
  if n in penal_scopes:
   scope='l’incrimination spécifique du CDD réprimant '+penal_scopes[n]+', ses amendes et sa peine de récidive'
   r['proposed_xml']='<p>Le présent article est abrogé à compter de l’entrée en vigueur de la loi instituant le contrat unique de travail. Les peines propres à '+penal_scopes[n]+' sont supprimées.</p>\n<p>Aucune poursuite ni condamnation ne peut être fondée sur cet article pour un fait postérieur à son abrogation. Les faits antérieurs sont traités selon les règles de la loi répressive plus douce ; les peines ne peuvent être maintenues par le seul renvoi aux dispositions transitoires des anciens contrats. Les conséquences des condamnations définitives restent régies par les règles générales qui leur sont applicables.</p>\n<p>Cette abrogation ne supprime ni les créances civiles et recours des salariés des contrats antérieurs, ni les protections autonomes de santé, de liberté et de non-discrimination. Le nouveau terme interdit relève de la reconnaissance du contrat unique prévue à l’article L. 1245-1 ; aucune amende ou peine de remplacement n’est instituée par le présent article.</p>'
   r['reason']='Réforme de fond : supprime '+scope+'. Le régime ancien de recours formel au CDD disparaît ; la qualification du contrat unique remplace la sanction future propre au terme, sans créer de peine.'
   r['benefit_review']='La suppression de ces peines bénéficie aux situations futures et, dans les conditions du droit pénal, aux faits antérieurs non définitivement jugés ou aux autres effets de la loi plus douce. Elle ne retire pas les créances civiles, droits de santé ou recours essentiels des salariés ; aucune amende nouvelle ne remplace la peine supprimée.'
  else:
   scope,legacy=scopes[n]
   r['proposed_xml']='<p>Le présent article est abrogé à compter de l’entrée en vigueur de la loi instituant le contrat unique de travail.</p>\n<p>'+legacy+'</p>\n<p>Les effets antérieurs qui restent légalement ouverts sont appréciés selon la rédaction antérieure, sous les réserves et conditions transitoires de l’article L. 1241-1. Cette réserve n’autorise aucun nouveau CDD ni nouveau renouvellement après la réforme et ne rétablit pas une formalité expressément supprimée.</p>'
   r['reason']='Réforme de fond : supprime pour l’avenir '+scope+'. La rédaction proposée est une abrogation opératoire avec transition des anciens contrats, et non une reformulation du régime CDD.'
   r['benefit_review']='Contrôle des avantages : '+legacy+' Les éventuelles dispenses, réductions, exceptions et conditions favorables de l’ancienne version restent prises en compte pour les situations conservées ; l’abolition du support CDD ne crée aucune obligation de remplacement.'
  r.update(change_type='full_repeal',repeal_policy_id='editorial_direction_2026_10_19',repeal_scope='Suppression pour l’avenir de '+scope+'. Les seules situations antérieures et dispositions autonomes expressément réservées subsistent.')
 r['review_notes']='Sources, notes DILA et proposition antérieure lues intégralement. Capture avant-image et garde du corps actuel dans source.json ; aucune inscription par cet auteur. Politique explicite du 19 octobre 2026 : nouveaux CDD et renouvellements interdits, anciens termes/primes/droits conservés, conversion avec ancienneté. Le noyau du contrat unique, l’essai et son barème sont rédigés séparément par rewrite_travail ; aucun texte de ce noyau n’est remplacé ici. Formation/intérim et les renvois extérieurs du reverse-inventory.json exigent leurs coordinations distinctes. Les dates historiques des notes ne sont pas la date de la réforme.'
 if n=='L1246-1':r['review_notes']+=' Anomalie source vérifiée sur la publication officielle actuelle de CNC L421-1 LEGIARTI000034592489 : ses 11°/12° ont été renumérotés en 2017 et visent actuellement séances cinématographiques/déclaration vidéographique. Aucun renvoi historique au travail illégal n’est rétabli silencieusement ; le volet source littéral distinct du CDD est conservé, à coordonner séparément si une correction de son objet est décidée.'
 if n=='D1243-1':r['review_notes']+=' Discordance source avec L1243-10(4°) signalée : la transition ne décide pas silencieusement de créer une prime exclue par l’ancien régime.'
 if n=='L1242-4':r['review_notes']+=' La note relative aux premières pensions paraît sans rapport avec le corps : elle reste conservée dans les sources, sans devenir une condition nouvelle.'
 r['proposed_sha256']=sha(r['proposed_xml']);rows.append(r)
assert len(rows)==70
(H/'answer.json.tmp').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n');(H/'answer.json.tmp').replace(H/'answer.json')
print(len(rows),'candidates',sum(r.get('change_type')=='full_repeal'for r in rows),'repeals')
